// Submit Add User
async function submitAddUser() {
  const email = document.getElementById("user-email").value.trim().toLowerCase();
  const nama = document.getElementById("user-nama").value.trim();
  const password = document.getElementById("user-password").value.trim();
  const role = document.getElementById("user-role").value;
  const kelasWaliId = document.getElementById("user-kelas-wali") ? document.getElementById("user-kelas-wali").value : "";
  const hariPiket = document.getElementById("user-hari-piket") ? document.getElementById("user-hari-piket").value : "";

  const session = getSession();
  const currentEmail = session ? session.email.toLowerCase() : "";
  const isPrimaryAdmin = currentEmail === "admin@smansaku.id";

  if (!email || !nama || !password) {
    alert("Semua field wajib diisi!");
    return;
  }

  // Simple email regex
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    alert("Format email tidak valid!");
    return;
  }

  const users = await getRegisteredUsers();
  if (users.some(u => u.email.toLowerCase() === email)) {
    alert("Email ini sudah terdaftar!");
    return;
  }

  // Save to Supabase cloud if available
  if (isCloudMode && supabase) {
    try {
      const { error } = await supabase.from("saku_guru_users").insert({ email, nama, password, role });
      if (error) {
        console.error("Supabase insert user error:", error);
        alert("Gagal menyimpan ke cloud: " + error.message);
        return;
      }
    } catch(e) {
      console.error("Supabase submitAddUser error:", e);
    }
  }

  try {
    let delList = JSON.parse(localStorage.getItem("saku_guru_deleted_users") || "[]");
    delList = delList.filter(em => em.toLowerCase() !== email);
    localStorage.setItem("saku_guru_deleted_users", JSON.stringify(delList));
  } catch(e) {}

  if (hariPiket) {
    savePiketAssignment(email, hariPiket);
  }

  // Jika ditugaskan sebagai wali kelas, sinkronkan ke db.kelas
  if (kelasWaliId) {
    const targetK = (db.kelas || []).find(k => String(k.id) === String(kelasWaliId));
    if (targetK) {
      targetK.waliKelasEmail = email;
      targetK.waliKelas = nama;
    }
  }
  await saveDatabase(true);
  await distributeMasterClassesToAllTeachers(db.kelas, db.siswa);

  users.push({ email, nama, password, role, kelasWaliId, hariPiket });
  await saveRegisteredUsers(users);

  closeModal();
  await loadUsersTable();
  initAppMode();
  showToast(`Akun ${nama} berhasil ditambahkan!`);
}

// Show Edit User Modal
async function showEditUserModal(email) {
  const users = await getRegisteredUsers();
  const user = users.find(u => u.email.toLowerCase() === email.toLowerCase());
  if (!user) return;

  const session = getSession();
  const currentEmail = session ? session.email.toLowerCase() : "";
  const targetEmail = user.email.toLowerCase();
  const isTargetPrimary = targetEmail === "admin@smansaku.id";
  const isPrimaryAdmin = currentEmail === "admin@smansaku.id";
  const hidePassword = isTargetPrimary && !isPrimaryAdmin;
  const isEmailLocked = isTargetPrimary;

  // Ambil kelas binaan saat ini jika ada
  const currentAssigned = (db.kelas || []).find(k => {
    if (k.waliKelasEmail && k.waliKelasEmail.toLowerCase() === user.email.toLowerCase()) return true;
    if (user.kelasWaliId && String(k.id) === String(user.kelasWaliId)) return true;
    return false;
  });
  const currentAssignedId = currentAssigned ? currentAssigned.id : (user.kelasWaliId || "");
  const userHariPiket = user.hariPiket || getUserHariPiket(user);

  const formHtml = `
    <input type="hidden" id="edit-user-old-email" value="${user.email}">
    <div class="form-group">
      <label class="form-label" for="edit-user-email">Email ${isEmailLocked ? '<span style="color:var(--accent); font-size:0.75rem;">(Terkunci - Akun Utama)</span>' : ''}</label>
      <input type="email" id="edit-user-email" class="form-control" value="${user.email}" ${isEmailLocked ? 'readonly style="background-color:var(--bg-secondary); cursor:not-allowed;"' : ''} required>
    </div>
    <div class="form-group">
      <label class="form-label" for="edit-user-nama">Nama Lengkap</label>
      <input type="text" id="edit-user-nama" class="form-control" value="${user.nama}" required>
    </div>
    ${hidePassword ? `
      <div class="form-group">
        <label class="form-label" for="edit-user-password">Password <span style="color:var(--accent); font-size:0.75rem;">(Terproteksi - Akun Utama)</span></label>
        <input type="password" id="edit-user-password" class="form-control" value="••••••••" readonly style="background-color:var(--bg-secondary); cursor:not-allowed;" title="Password Akun Utama terproteksi dan hanya dapat diubah oleh Administrator Utama">
        <small style="color:var(--text-muted); font-size:0.75rem; display:block; margin-top:4px;">
          <i class="fas fa-lock"></i> Password Akun Utama terproteksi dan hanya dapat diubah oleh Akun Utama itu sendiri.
        </small>
      </div>
    ` : `
      <div class="form-group">
        <label class="form-label" for="edit-user-password">Password</label>
        <input type="text" id="edit-user-password" class="form-control" value="${escapeHtml(user.password)}" required>
      </div>
    `}
    <div class="form-group">
      <label class="form-label" for="edit-user-role">Peran (Role)</label>
      <select id="edit-user-role" class="form-control" required>
        <option value="guru" ${user.role === 'guru' ? 'selected' : ''}>Guru Mata Pelajaran</option>
        <option value="guru_piket" ${user.role === 'guru_piket' ? 'selected' : ''}>Guru Piket Sekolah</option>
        <option value="guru_bk" ${user.role === 'guru_bk' ? 'selected' : ''}>Guru BK (Bimbingan Konseling)</option>
        <option value="admin" ${user.role === 'admin' ? 'selected' : ''}>Administrator</option>
      </select>
      <small style="color:var(--text-muted); font-size:0.75rem; display:block; margin-top:4px;">
        <i class="fas fa-info-circle"></i> Tentukan hak akses akun: Guru Mapel, Guru Piket, Guru BK, atau Administrator.
      </small>
    </div>
    <div class="form-group" id="group-edit-user-hari-piket">
      <label class="form-label" for="edit-user-hari-piket">Penugasan Hari Guru Piket</label>
      <select id="edit-user-hari-piket" class="form-control">
        <option value="">— Bukan Guru Piket / Semua Hari —</option>
        <option value="Senin" ${userHariPiket === 'Senin' ? 'selected' : ''}>Hari Senin (Laporan Khusus Hari Senin)</option>
        <option value="Selasa" ${userHariPiket === 'Selasa' ? 'selected' : ''}>Hari Selasa (Laporan Khusus Hari Selasa)</option>
        <option value="Rabu" ${userHariPiket === 'Rabu' ? 'selected' : ''}>Hari Rabu (Laporan Khusus Hari Rabu)</option>
        <option value="Kamis" ${userHariPiket === 'Kamis' ? 'selected' : ''}>Hari Kamis (Laporan Khusus Hari Kamis)</option>
        <option value="Jumat" ${userHariPiket === 'Jumat' ? 'selected' : ''}>Hari Jumat (Laporan Khusus Hari Jumat)</option>
        <option value="Sabtu" ${userHariPiket === 'Sabtu' ? 'selected' : ''}>Hari Sabtu (Laporan Khusus Hari Sabtu)</option>
      </select>
      <small style="color:var(--text-muted); font-size:0.75rem; display:block; margin-top:4px;">
        <i class="fas fa-info-circle"></i> Jika akun piket ditetapkan hari tugas (misal: Hari Senin), laporan kehadiran seluruh kelas yang tampil hanya khusus hari Senin.
      </small>
    </div>
    <div class="form-group" id="group-edit-user-kelas-wali">
      <label class="form-label" for="edit-user-kelas-wali">Penugasan Wali Kelas</label>
      <select id="edit-user-kelas-wali" class="form-control">
        <option value="">— Bukan Wali Kelas —</option>
        ${(db.kelas || []).map(k => {
          const isSelected = String(k.id) === String(currentAssignedId);
          const currentHolder = k.waliKelas && (!k.waliKelasEmail || k.waliKelasEmail.toLowerCase() !== user.email.toLowerCase()) ? ` (Saat ini: ${escapeHtml(k.waliKelas)})` : '';
          return `<option value="${k.id}" ${isSelected ? 'selected' : ''}>Kelas ${escapeHtml(k.nama)}${currentHolder}</option>`;
        }).join("")}
      </select>
      <small style="color:var(--text-muted); font-size:0.75rem; display:block; margin-top:4px;">
        <i class="fas fa-info-circle"></i> Jika akun guru ditugaskan sebagai wali kelas, Mode Wali Kelas otomatis aktif dan langsung terkoneksi ke kelas ini.
      </small>
    </div>
  `;

  const footerHtml = `
    <button class="btn btn-secondary" onclick="closeModal()">Batal</button>
    <button class="btn btn-primary" onclick="submitEditUser()">Simpan Perubahan</button>
  `;

  openModal("Edit Akun Pengguna", formHtml, footerHtml);
}

// Submit Edit User
async function submitEditUser() {
  const oldEmail = document.getElementById("edit-user-old-email").value.toLowerCase();
  let email = document.getElementById("edit-user-email").value.trim().toLowerCase();
  const nama = document.getElementById("edit-user-nama").value.trim();
  const password = document.getElementById("edit-user-password").value.trim();
  const roleInput = document.getElementById("edit-user-role");
  let role = roleInput ? roleInput.value : "guru";
  const kelasWaliId = document.getElementById("edit-user-kelas-wali") ? document.getElementById("edit-user-kelas-wali").value : "";
  const hariPiket = document.getElementById("edit-user-hari-piket") ? document.getElementById("edit-user-hari-piket").value : "";

  const session = getSession();
  const currentEmail = session ? session.email.toLowerCase() : "";
  const isPrimaryAdmin = currentEmail === "admin@smansaku.id";
  const isTargetPrimary = oldEmail === "admin@smansaku.id";
  const hidePassword = isTargetPrimary && !isPrimaryAdmin;

  if (!email || !nama || (!password && !hidePassword)) {
    alert("Semua field wajib diisi!");
    return;
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    alert("Format email tidak valid!");
    return;
  }

  const users = await getRegisteredUsers();
  if (email !== oldEmail && users.some(u => u.email.toLowerCase() === email)) {
    alert("Email ini sudah terdaftar untuk pengguna lain!");
    return;
  }

  const userIdx = users.findIndex(u => u.email.toLowerCase() === oldEmail);
  if (userIdx === -1) {
    alert("Data akun tidak ditemukan!");
    return;
  }

  const targetUser = users[userIdx];
  const finalPassword = hidePassword ? targetUser.password : password;

  // Proteksi: Jika peran Administrator diubah menjadi non-admin, pastikan masih ada setidaknya 1 Administrator lain di sistem
  if (targetUser.role === "admin" && role !== "admin") {
    const otherAdmins = users.filter(u => u.role === "admin" && u.email.toLowerCase() !== oldEmail);
    if (otherAdmins.length === 0) {
      alert("Tidak dapat mengubah peran ini menjadi non-administrator karena harus ada setidaknya 1 akun Administrator aktif di sistem!");
      return;
    }
  }

  // Akun utama (admin@smansaku.id) email tidak pernah boleh diubah
  if (isTargetPrimary) {
    email = "admin@smansaku.id";
  }

  // If email changes, migrate database key in localStorage
  if (email !== oldEmail) {
    const oldKey = "saku_guru_db_" + oldEmail.replace(/[^a-z0-9]/g, "_");
    const newKey = "saku_guru_db_" + email.replace(/[^a-z0-9]/g, "_");
    const oldData = localStorage.getItem(oldKey);
    if (oldData) {
      localStorage.setItem(newKey, oldData);
      localStorage.removeItem(oldKey);
    }
  }

  // Save to Supabase cloud if available
  if (isCloudMode && supabase) {
    try {
      if (email !== oldEmail) {
        // Supabase Safe Migration: Write-Before-Delete
        const { data: dbRow } = await supabase.from("saku_guru_databases").select("data").eq("email", oldEmail).maybeSingle();
        const oldDbData = dbRow ? dbRow.data : null;

        await supabase.from("saku_guru_users").insert({ email, nama, password: finalPassword, role });

        if (oldDbData) {
          await supabase.from("saku_guru_databases").upsert({ email, data: oldDbData, updated_at: new Date().toISOString() }, { onConflict: "email" });
        }

        await supabase.from("saku_guru_users").delete().eq("email", oldEmail);
        if (oldDbData) {
          await supabase.from("saku_guru_databases").delete().eq("email", oldEmail);
        }
      } else {
        await supabase.from("saku_guru_users").update({ nama, password: finalPassword, role }).eq("email", email);
      }
    } catch(e) {
      console.error("Supabase submitEditUser error:", e);
    }
  }

  // Sinkronisasi penugasan piket
  if (oldEmail !== email) {
    savePiketAssignment(oldEmail, "");
  }
  savePiketAssignment(email, hariPiket);

  // Sinkronisasi kelas binaan di db.kelas
  (db.kelas || []).forEach(k => {
    if (k.waliKelasEmail && k.waliKelasEmail.toLowerCase() === oldEmail.toLowerCase()) {
      k.waliKelasEmail = "";
      k.waliKelas = "";
    }
  });

  if (kelasWaliId) {
    const targetK = (db.kelas || []).find(k => String(k.id) === String(kelasWaliId));
    if (targetK) {
      targetK.waliKelasEmail = email;
      targetK.waliKelas = nama;
    }
  }
  await saveDatabase(true);
  await distributeMasterClassesToAllTeachers(db.kelas, db.siswa);

  // Perbarui objek di array users
  users[userIdx] = { ...users[userIdx], email, nama, password: finalPassword, role, kelasWaliId, hariPiket };
  await saveRegisteredUsers(users);

  // If the edited user is the current session user, update session
  if (session && session.email.toLowerCase() === oldEmail.toLowerCase()) {
    session.email = email;
    session.nama = nama;
    session.role = role;
    session.kelasWaliId = kelasWaliId;
    session.hariPiket = hariPiket;
    setSession(session);
    updateHeaderProfile();
    initAppMode();
  }

  closeModal();
  await loadUsersTable();
  initAppMode();

  let roleLabel = "Guru Mapel";
  if (role === "admin") roleLabel = "Administrator";
  else if (role === "guru_bk") roleLabel = "Guru BK";

  showToast(`Akun ${nama} berhasil diperbarui (Peran: ${roleLabel})!`);
}

// Delete User
async function deleteUser(email) {
  const session = getSession();
  const currentEmail = session ? session.email.toLowerCase() : "";
  const isPrimaryAdmin = currentEmail === "admin@smansaku.id";
  const targetEmail = (email || "").toLowerCase().trim();

  // 1. Akun utama (admin@smansaku.id) tidak dapat dihapus oleh siapa pun
  if (targetEmail === "admin@smansaku.id") {
    alert("Akun Administrator Utama (admin@smansaku.id) adalah akun utama yang tidak dapat dihapus!");
    return;
  }

  // 2. Akun sendiri yang sedang aktif tidak dapat dihapus
  if (currentEmail === targetEmail) {
    alert("Anda tidak dapat menghapus akun Anda sendiri yang sedang aktif!");
    return;
  }

  const users = await getRegisteredUsers();
  const targetUser = users.find(u => u.email.toLowerCase() === targetEmail);
  if (!targetUser) {
    alert("Akun tidak ditemukan!");
    return;
  }

  // 3. Akun admin lainnya hanya bisa dihapus oleh akun admin@smansaku.id
  if (targetUser.role === "admin") {
    if (!isPrimaryAdmin) {
      alert("Akses ditolak: Akun Administrator hanya bisa dihapus oleh Akun Utama (admin@smansaku.id)!");
      return;
    }
  }

  if (confirm(`Apakah Anda yakin ingin menghapus akun ${targetUser.nama} (${targetEmail})? Akun ini tidak akan dapat login lagi.`)) {
    // 1. Catat ke daftar akun terhapus agar tidak di-reseed otomatis
    try {
      const delList = JSON.parse(localStorage.getItem("saku_guru_deleted_users") || "[]");
      if (!delList.includes(targetEmail)) {
        delList.push(targetEmail);
        localStorage.setItem("saku_guru_deleted_users", JSON.stringify(delList));
      }
    } catch(e) {}

    // 2. Hapus dari Supabase cloud jika terhubung
    if (isCloudMode && supabase) {
      try {
        await supabase.from("saku_guru_databases").delete().eq("email", targetEmail);
        const { error } = await supabase.from("saku_guru_users").delete().eq("email", targetEmail);
        if (error) {
          console.error("Supabase deleteUser error:", error);
        }
      } catch(e) {
        console.error("Supabase deleteUser error:", e);
      }
    }

    savePiketAssignment(targetEmail, "");

    // 3. Bersihkan dari penetapan wali kelas jika akun ini adalah wali kelas
    let classChanged = false;
    (db.kelas || []).forEach(k => {
      if (k.waliKelasEmail && k.waliKelasEmail.toLowerCase() === targetEmail) {
        k.waliKelasEmail = "";
        k.waliKelas = "";
        classChanged = true;
      }
    });
    if (classChanged) {
      await saveDatabase(true);
      await distributeMasterClassesToAllTeachers(db.kelas, db.siswa);
    }

    // 4. Perbarui daftar akun lokal
    let updatedUsers = (users || []).filter(u => u && u.email && u.email.toLowerCase() !== targetEmail);
    await saveRegisteredUsers(updatedUsers);

    // 5. Hapus database lokal pengguna ini
    const dbKey = "saku_guru_db_" + targetEmail.replace(/[^a-z0-9]/g, "_");
    localStorage.removeItem(dbKey);

    await loadUsersTable();
    showToast(`Akun ${targetEmail} berhasil dihapus.`);
  }
}

function addSubjectInputField(value = "") {
  const container = document.getElementById("subject-inputs-container");
  if (!container) return;
  const div = document.createElement("div");
  div.style.display = "flex";
  div.style.gap = "8px";
  div.className = "subject-input-row";
  div.innerHTML = `
    <input type="text" class="form-control subject-input-item" value="${value}" placeholder="Nama Mata Pelajaran..." required>
    <button class="btn btn-danger btn-sm" onclick="this.parentElement.remove()" style="padding: 10px 14px;"><i class="fas fa-trash"></i></button>
  `;
  container.appendChild(div);
}

function submitProfile() {
  const nama = document.getElementById("prof-nama").value.trim();
  const nip = document.getElementById("prof-nip").value.trim();
  const sekolah = document.getElementById("prof-sekolah").value.trim();
  const alamat = document.getElementById("prof-alamat").value.trim();
  const kepalaSekolah = document.getElementById("prof-kepsek").value.trim();
  const kepalaSekolahNip = document.getElementById("prof-kepsek-nip").value.trim();

  if (!nama || !sekolah) {
    alert("Nama Guru dan Sekolah wajib diisi!");
    return;
  }

  // Collect subjects
  const inputItems = document.querySelectorAll(".subject-input-item");
  const subjects = [];
  inputItems.forEach(input => {
    const val = input.value.trim();
    if (val && !subjects.includes(val)) {
      subjects.push(val);
    }
  });

  if (subjects.length === 0) {
    alert("Harap masukkan minimal satu mata pelajaran!");
    return;
  }

  // Get image Base64 data from preview images
  const fotoImg = document.querySelector("#prof-photo-preview img");
  const logoImg = document.querySelector("#school-logo-preview img");
  const foto = fotoImg ? fotoImg.src : null;
  const logo = logoImg ? logoImg.src : null;

  // Update profile and subjects in state
  db.guruProfile = { 
    ...(db.guruProfile || {}),
    nama, 
    nip, 
    sekolah, 
    alamat,
    kepalaSekolah,
    kepalaSekolahNip,
    foto: foto || (db.guruProfile ? db.guruProfile.foto : null),
    logo: logo || (db.guruProfile ? db.guruProfile.logo : null),
    mapel: subjects.join(", "),
    mapelAmpu: subjects
  };

  // Pastikan master kurikulum sekolah tetap utuh dan mapel yang diampu guru tersimpan
  ensureCompleteSchoolMapel(db);
  subjects.forEach(s => {
    if (s && !db.mapel.includes(s)) {
      db.mapel.push(s);
    }
  });

  saveDatabase();
  if (typeof updateHeaderProfile === "function") {
    updateHeaderProfile();
  }
  showToast("Profil dan mata pelajaran yang diampu berhasil disimpan!");
}

function handleImageUpload(inputEl, type) {
  const file = inputEl.files[0];
  if (!file) return;

  compressImage(file, type, (dataUrl) => {
    if (type === 'foto') {
      const preview = document.getElementById("prof-photo-preview");
      preview.innerHTML = `<img src="${dataUrl}" style="width: 100%; height: 100%; object-fit: cover;">`;
    } else if (type === 'logo') {
      const preview = document.getElementById("school-logo-preview");
      preview.innerHTML = `<img src="${dataUrl}" style="width: 100%; height: 100%; object-fit: contain; padding: 4px;">`;
    }
  });
}

function compressImage(file, type, callback) {
  const reader = new FileReader();
  reader.readAsDataURL(file);
  reader.onload = function(event) {
    const img = new Image();
    img.src = event.target.result;
    img.onload = function() {
      const canvas = document.createElement("canvas");
      const max_size = 180; // Resize to max 180px for space efficiency in localStorage
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > max_size) {
          height *= max_size / width;
          width = max_size;
        }
      } else {
        if (height > max_size) {
          width *= max_size / height;
          height = max_size;
        }
      }
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, width, height);

      if (type === 'logo') {
        makeBackgroundTransparent(canvas);
      }

      // 60% quality JPEG is lightweight for foto, PNG for logo to preserve transparency
      const outputFormat = type === 'logo' ? "image/png" : "image/jpeg";
      const dataUrl = canvas.toDataURL(outputFormat, outputFormat === "image/jpeg" ? 0.6 : undefined);
      callback(dataUrl);
    };
  };
}

function makeBackgroundTransparent(canvas) {
  const ctx = canvas.getContext("2d");
  const width = canvas.width;
  const height = canvas.height;
  try {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    
    // Helper to get index
    const getIndex = (x, y) => (y * width + x) * 4;
    
    // Helper to check if a pixel is near white/light grey (background)
    const isNearWhite = (x, y) => {
      const idx = getIndex(x, y);
      const r = data[idx];
      const g = data[idx + 1];
      const b = data[idx + 2];
      const a = data[idx + 3];
      // Check if pixel is not already transparent and is light (near white)
      return a > 0 && r > 230 && g > 230 && b > 230;
    };
    
    const visited = new Uint8Array(width * height);
    const queue = [];
    
    // Add all border pixels that are near white to the queue
    for (let x = 0; x < width; x++) {
      if (isNearWhite(x, 0)) {
        const idx = 0 * width + x;
        visited[idx] = 1;
        queue.push([x, 0]);
      }
      if (isNearWhite(x, height - 1)) {
        const idx = (height - 1) * width + x;
        visited[idx] = 1;
        queue.push([x, height - 1]);
      }
    }
    for (let y = 0; y < height; y++) {
      if (isNearWhite(0, y)) {
        const idx = y * width + 0;
        if (!visited[idx]) {
          visited[idx] = 1;
          queue.push([0, y]);
        }
      }
      if (isNearWhite(width - 1, y)) {
        const idx = y * width + (width - 1);
        if (!visited[idx]) {
          visited[idx] = 1;
          queue.push([width - 1, y]);
        }
      }
    }
    
    // Breadth-First Search (BFS) to flood fill transparent background
    let head = 0;
    while (head < queue.length) {
      const [cx, cy] = queue[head++];
      
      const idx = getIndex(cx, cy);
      data[idx + 3] = 0; // Set alpha to 0 (fully transparent)
      
      // Check 4-way neighbors
      const neighbors = [
        [cx + 1, cy],
        [cx - 1, cy],
        [cx, cy + 1],
        [cx, cy - 1]
      ];
      
      for (const [nx, ny] of neighbors) {
        if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
          const nIdx = ny * width + nx;
          if (!visited[nIdx] && isNearWhite(nx, ny)) {
            visited[nIdx] = 1;
            queue.push([nx, ny]);
          }
        }
      }
    }
    
    ctx.putImageData(imageData, 0, 0);
  } catch (e) {
    console.error("Error making background transparent:", e);
  }
}

async function triggerSeedData() {
  if (confirm("Apakah Anda ingin memuat data awal? Tindakan ini akan menimpa data Anda saat ini.")) {
    await loadSeedData();
    // Re-render settings page to reflect new values
    renderPage("profil");
  }
}

async function triggerResetDatabase() {
  if (confirm("PENTING: Apakah Anda yakin ingin menghapus semua data? Seluruh data siswa, kelas, jadwal, nilai, dan absensi akan hilang selamanya.")) {
    await resetDatabase();
    renderPage("profil");
  }
}

function exportDatabaseJSON() {
  try {
    const dataStr = JSON.stringify(db, null, 2);
    const dataBlob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement("a");
    const session = getSession();
    const namePrefix = session && session.email ? session.email.split("@")[0] : "guest";
    const dateStr = new Date().toISOString().split("T")[0];
    
    link.href = url;
    link.download = `sman_saku_backup_${namePrefix}_${dateStr}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    showToast("Database berhasil diekspor!");
  } catch (e) {
    console.error("Export database error:", e);
    alert("Gagal mengekspor database: " + e.message);
  }
}

function importDatabaseJSON(event) {
  const file = event.target.files[0];
  if (!file) return;
  
  const reader = new FileReader();
  reader.onload = async function(e) {
    try {
      const parsed = JSON.parse(e.target.result);
      if (parsed && typeof parsed === "object") {
        // Self-repair schema validation
        parsed.guruProfile = parsed.guruProfile || { nama: "Nama Guru, S.Pd.", nip: "" };
        parsed.kelas = parsed.kelas || [];
        parsed.siswa = parsed.siswa || [];
        parsed.absensi = parsed.absensi || [];
        parsed.nilai = parsed.nilai || [];
        parsed.jurnal = parsed.jurnal || [];
        parsed.jadwal = parsed.jadwal || [];
        parsed.mapel = parsed.mapel || ["Matematika", "Fisika", "Kimia", "Biologi", "Bahasa Indonesia", "Bahasa Inggris"];
        
        if (confirm("Apakah Anda yakin ingin memulihkan database dari file cadangan ini? Tindakan ini akan menimpa seluruh data Anda saat ini.")) {
          db = parsed;
          delete db.is_demo; // User uploaded database is not demo data
          await saveDatabase();
          showToast("Database berhasil dipulihkan dari file cadangan!");
          renderPage("profil"); // Re-render settings page
        }
      } else {
        alert("Format file JSON cadangan tidak valid!");
      }
    } catch (err) {
      console.error("Import database error:", err);
      alert("Gagal membaca berkas cadangan: Format JSON tidak valid.");
    }
    // Clear input value so same file can be selected again
    event.target.value = "";
  };
  reader.readAsText(file);
}

// ============================================================================
// SISTEM MULTI-MODE: GURU MAPEL, WALI KELAS, & GURU WALI (MENTOR ASUHAN)
// ============================================================================

let currentAppMode = localStorage.getItem("sman_saku_mode") || "mapel";

function getAppMode() {
  return currentAppMode;
}

function initAppMode() {
  const session = getSession();
  const userRole = session ? session.role : "guru";
  const allowedModes = getAllowedModesForRole(userRole, session);

  const savedMode = localStorage.getItem("sman_saku_mode");
  if (savedMode && allowedModes.includes(savedMode)) {
    currentAppMode = savedMode;
  } else {
    // Default to first allowed mode for this user's role (e.g. gurubk for guru_bk, mapel for guru)
    currentAppMode = allowedModes[0];
    localStorage.setItem("sman_saku_mode", currentAppMode);
  }

  // Self-repair DB structures for Wali Kelas, Guru Wali, & Guru BK
  if (typeof db !== "undefined" && db) {
    db.catatanWali = db.catatanWali || [];
    db.siswaAsuhan = db.siswaAsuhan || [];
    db.jurnalBimbingan = db.jurnalBimbingan || [];
    db.academicFollowUp = db.academicFollowUp || {};
    db.layananBK = db.layananBK || [];
    db.peminatanKarirBK = db.peminatanKarirBK || [];
    db.agendaBK = db.agendaBK || [];
    db.kelasBimbinganBK = db.kelasBimbinganBK || [];
    db.jurnalPiket = db.jurnalPiket || [];

    const assignedClass = session ? getAssignedWaliKelas(session) : null;
    if (assignedClass) {
      const classStudents = getStudentsForClass(assignedClass.id);
      if (classStudents && classStudents.length > 0) {
        const validAsuhan = db.siswaAsuhan.filter(id => db.siswa.some(s => s.id === id));
        if (validAsuhan.length === 0) {
          db.siswaAsuhan = classStudents.map(s => s.id);
        }
      }
    } else if (db.siswaAsuhan.length === 0 && (db.siswa && db.siswa.length > 0)) {
      const candidates = ["s-3", "s-5", "s-8"].filter(id => db.siswa.some(s => s.id === id));
      db.siswaAsuhan = candidates.length > 0 ? candidates : db.siswa.slice(0, 3).map(s => s.id);
    }

    // Default kelas bimbingan BK to all classes if empty and classes exist
    if (db.kelasBimbinganBK.length === 0 && (db.kelas && db.kelas.length > 0)) {
      db.kelasBimbinganBK = db.kelas.map(k => k.id);
    }

    // Seed realistic sample BK data if empty and students exist
    if (db.layananBK.length === 0 && (db.siswa && db.siswa.length > 0)) {
      const s1 = db.siswa[0];
      const s2 = db.siswa[1] || db.siswa[0];
      const today = getLocalDateString();
      db.layananBK = [
        {
          id: "bk-sample-1",
          tanggal: today,
          waktu: "08:30",
          siswaId: s1.id,
          kelasId: s1.kelasId || "",
          bidang: "Belajar",
          jenisLayanan: "Konseling Individu",
          urgensi: "Sedang",
          sumber: "Rujukan Wali Kelas",
          gejala: "Kesulitan konsentrasi saat jam belajar dan motivasi menurun.",
          uraian: "Siswa diajak mengeksplorasi gaya belajar yang cocok, penyebab kejenuhan, dan menyusun target harian realistis.",
          tindakLanjut: "Pembuatan jadwal belajar mandiri di rumah dan pemantauan berkala Guru BK.",
          status: "Dalam Proses",
          catatan: "Siswa kooperatif dan berjanji memperbaiki ritme belajar.",
          createdAt: new Date().toISOString()
        },
        {
          id: "bk-sample-2",
          tanggal: today,
          waktu: "10:15",
          siswaId: s2.id,
          kelasId: s2.kelasId || "",
          bidang: "Karir",
          jenisLayanan: "Konseling Individu",
          urgensi: "Biasa",
          sumber: "Inisiatif Siswa (Sukarela)",
          gejala: "Konsultasi pemilihan jurusan perguruan tinggi negeri (SNBP / SNBT).",
          uraian: "Menganalisis ledger nilai semester 1-4, minat bakat, dan peluang keketatan program studi yang diminati.",
          tindakLanjut: "Mengarahkan siswa mengikuti asesmen minat bakat karir dan diskusi lanjutan bersama orang tua.",
          status: "Tuntas",
          catatan: "Siswa mantap memilih rumpun Saintek/Teknik dan mempersiapkan portofolio.",
          createdAt: new Date().toISOString()
        }
      ];
    }

    if (db.agendaBK.length === 0 && (db.siswa && db.siswa.length > 0)) {
      const s1 = db.siswa[0];
      const today = getLocalDateString();
      db.agendaBK = [
        {
          id: "ag-sample-1",
          tanggal: today,
          waktu: "13:00",
          siswaId: s1.id,
          kegiatan: "Sesi Konseling Lanjutan & Evaluasi RTL",
          tempat: "Ruang BK",
          status: "Terjadwal",
          keterangan: "Evaluasi perkembangan jadwal belajar mandiri dan koordinasi tugas sekolah.",
          createdAt: new Date().toISOString()
        }
      ];
    }

    if (db.jurnalPiket.length === 0 && (db.siswa && db.siswa.length > 0)) {
      const today = getLocalDateString();
      db.jurnalPiket = [
        {
          id: "piket-sample-1",
          tanggal: today,
          waktu: "07:15",
          tipe: "Keterlambatan Gerbang",
          judul: "Penertiban Siswa Terlambat Masuk",
          uraian: "Pencatatan 3 siswa yang tiba setelah pukul 07.15 karena kendala cuaca hujan gerimis di jalan.",
          petugas: session ? session.nama : "Guru Piket Sekolah, S.Pd.",
          tindakLanjut: "Diberikan pengarahan disiplin di pos piket, dicatat di buku kehadiran, dan diizinkan masuk ke kelas masing-masing.",
          status: "Selesai",
          createdAt: new Date().toISOString()
        }
      ];
    }

    if (typeof seedSamplePiketAttendanceForMonday === "function") {
      seedSamplePiketAttendanceForMonday();
    }
  }

  updateModeSwitcherUI(currentAppMode);
  renderSidebarMenu();

  // Close dropdown on outside click
  document.addEventListener("click", function(e) {
    const container = document.getElementById("mode-switcher-container");
    if (container && !container.contains(e.target)) {
      closeModeDropdown();
    }
  });
}

function toggleModeDropdown(event) {
  if (event) event.stopPropagation();
  const dropdown = document.getElementById("mode-dropdown-menu");
  const container = document.getElementById("mode-switcher-container");
  if (!dropdown) return;
  const isHidden = dropdown.style.display === "none" || !dropdown.style.display;
  if (isHidden) {
    updateModeSwitcherUI(currentAppMode);
    dropdown.style.display = "block";
    if (container) container.classList.add("open");
  } else {
    closeModeDropdown();
  }
}

function closeModeDropdown() {
  const dropdown = document.getElementById("mode-dropdown-menu");
  const container = document.getElementById("mode-switcher-container");
  if (dropdown) dropdown.style.display = "none";
  if (container) container.classList.remove("open");
}

function setAppMode(mode) {
  const session = getSession();
  const userRole = session ? session.role : "guru";
  const allowedModes = getAllowedModesForRole(userRole, session);

  if (!allowedModes.includes(mode)) {
    showToast("Akses ditolak: Mode ini tidak tersedia untuk jenis akun Anda.");
    return;
  }
  currentAppMode = mode;
  localStorage.setItem("sman_saku_mode", mode);
  closeModeDropdown();
  updateModeSwitcherUI(mode);
  renderSidebarMenu();

  let toastMsg = "Beralih ke Mode Guru Mapel";
  if (mode === "walikelas") toastMsg = "Beralih ke Mode Wali Kelas";
  if (mode === "guruwali") toastMsg = "Beralih ke Mode Guru Wali";
  if (mode === "gurubk") toastMsg = "Beralih ke Mode Guru BK (Bimbingan Konseling)";
  if (mode === "gurupiket") toastMsg = "Beralih ke Mode Guru Piket (Piket Harian Seluruh Kelas)";
  showToast(toastMsg);

  // Sinkronkan data terbaru saat beralih mode
  const userSchool = getCurrentSchoolName();
  syncCrossAccountDataLocally(db, userSchool);
  if (isCloudMode && supabase) {
    syncCrossAccountDataFromCloud(db, userSchool, false).then(updated => {
      if (updated) {
        const activeNav = document.querySelector(".sidebar-menu li.active");
        const activePage = activeNav ? activeNav.getAttribute("data-page") : "dashboard";
        if (typeof renderPage === "function" && activePage) renderPage(activePage);
      }
    }).catch(e => console.warn(e));
  }

  navigate("dashboard");
}

function updateModeSwitcherUI(mode) {
  const session = getSession();
  const userRole = session ? session.role : "guru";
  const allowedModes = getAllowedModesForRole(userRole, session);

  const btn = document.getElementById("btn-switch-mode");
  const icon = document.getElementById("mode-icon");
  const title = document.getElementById("mode-active-title");

  if (btn) {
    btn.className = `btn-mode-switcher mode-${mode}`;
  }

  if (icon) {
    if (mode === "walikelas") {
      icon.className = "fas fa-user-tie";
    } else if (mode === "guruwali") {
      icon.className = "fas fa-hand-holding-heart";
    } else if (mode === "gurubk") {
      icon.className = "fas fa-user-shield";
    } else if (mode === "gurupiket") {
      icon.className = "fas fa-clipboard-check";
    } else {
      icon.className = "fas fa-chalkboard-user";
    }
  }

  if (title) {
    if (mode === "walikelas") {
      title.textContent = "Wali Kelas";
    } else if (mode === "guruwali") {
      title.textContent = "Guru Wali";
    } else if (mode === "gurubk") {
      title.textContent = "Guru BK";
    } else if (mode === "gurupiket") {
      title.textContent = "Guru Piket";
    } else {
      title.textContent = "Guru Mapel";
    }
  }

  document.querySelectorAll(".mode-dropdown-item").forEach(item => {
    const itemMode = item.getAttribute("data-mode");
    // Sembunyikan mode yang tidak diizinkan untuk peran akun ini
    if (!allowedModes.includes(itemMode)) {
      item.style.display = "none";
      return;
    }
    item.style.display = "flex";

    if (itemMode === mode) {
      item.classList.add("active");
      const badge = item.querySelector(".item-badge");
      if (badge) {
        if (itemMode === "walikelas") {
          const assigned = getAssignedWaliKelas(session);
          badge.textContent = assigned ? `Aktif (${assigned.nama})` : "Aktif";
        } else {
          badge.textContent = "Aktif";
        }
      }
    } else {
      item.classList.remove("active");
      const badge = item.querySelector(".item-badge");
      if (badge) {
        if (itemMode === "mapel") badge.textContent = "Mapel";
        if (itemMode === "walikelas") {
          const assigned = getAssignedWaliKelas(session);
          badge.textContent = assigned ? `Kelas ${assigned.nama}` : "Kelas Binaan";
        }
        if (itemMode === "guruwali") badge.textContent = "Mentor Asuhan";
        if (itemMode === "gurubk") badge.textContent = "Konseling & Karir";
        if (itemMode === "gurupiket") badge.textContent = "Piket Harian";
      }
    }
  });
}

